import { TABLES } from './src/generated/registry.mjs';

function normalizeCode(code) {
  return code.trim().toUpperCase();
}

const tests = [
  { code: 'PLGDN', label: 'uppercase' },
  { code: 'plgdn', label: 'lowercase' },
  { code: ' PLGDN ', label: 'with spaces' }
];

for (const test of tests) {
  const normalized = normalizeCode(test.code);
  const result = TABLES.ports[normalized];
  if (result && result.name === 'Gdansk' && result.max_draft_dm === 150) {
